#!/usr/bin/env python3
# Weight exporter for __NAME__ — generated by jacq.
#
# Downloads the HuggingFace model and writes each weight as a raw binary in the layout the
# generated CUDA runtime expects (row-major [out, in]; q/k/v fused; gate/up fused). For
# dtype=int8/int4, the four large linear matrices (qkv, o, gate_up, down) are stored per-output-row
# symmetric: int8 one byte per weight, or int4 packed two weights per byte (`<name>.bin`), plus an
# fp16 scale vector (`<name>.scale.bin`); norms, embedding, and lm_head stay fp16. Also writes a
# tokenized test prompt and a reference greedy continuation the runtime output should match.
import os
import sys

import numpy as np
import torch
from transformers import AutoModelForCausalLM, AutoTokenizer

SOURCE = "__SOURCE__"
LAYERS = __LAYERS__
DTYPE = "__DTYPE__"
INT8 = DTYPE == "int8"
INT4 = DTYPE == "int4"
ATTN_BIAS = __ATTN_BIAS__  # q/k/v projections carry a bias (Qwen2); fused into layer{l}_qkv_bias.bin
LORA = __LORA__                  # also export a LoRA adapter from LORA_SOURCE
LORA_SOURCE = "__LORA_SOURCE__"  # HuggingFace peft adapter repo (or local dir)
LORA_TARGETS = __LORA_TARGETS__  # e.g. ["w_q", "w_k", "w_v", "w_o"]


def main():
    out_dir = sys.argv[1] if len(sys.argv) > 1 else "weights"
    os.makedirs(out_dir, exist_ok=True)
    device = "cuda" if torch.cuda.is_available() else "cpu"

    print(f"loading {SOURCE} on {device} (dtype={DTYPE}) ...")
    model = AutoModelForCausalLM.from_pretrained(SOURCE, torch_dtype=torch.float16).to(device)
    model.eval()
    sd = model.state_dict()

    def save_fp16(name, t):
        t.detach().to(torch.float16).cpu().numpy().tofile(os.path.join(out_dir, name))

    def save_scale(base, scale):
        scale.squeeze(1).to(torch.float16).cpu().numpy().tofile(os.path.join(out_dir, base + ".scale.bin"))

    def save_lin(base, W):
        # Linear weight [out, in]: fp16, or per-output-row symmetric int8/int4 + fp16 scale.
        if INT8:
            Wf = W.detach().float()
            scale = (Wf.abs().amax(dim=1, keepdim=True) / 127.0).clamp(min=1e-8)  # [out, 1]
            Wq = torch.round(Wf / scale).clamp(-127, 127).to(torch.int8)          # [out, in]
            Wq.cpu().numpy().tofile(os.path.join(out_dir, base + ".bin"))
            save_scale(base, scale)
        elif INT4:
            Wf = W.detach().float()
            assert Wf.shape[1] % 2 == 0, f"{base}: in_dim {Wf.shape[1]} must be even to pack int4"
            scale = (Wf.abs().amax(dim=1, keepdim=True) / 7.0).clamp(min=1e-8)         # [out, 1]
            q = torch.round(Wf / scale).clamp(-7, 7).to(torch.int8).cpu().numpy()      # [out, in]
            lo = (q[:, 0::2] & 0x0F).astype(np.uint8)   # col 2i -> low nibble
            hi = (q[:, 1::2] & 0x0F).astype(np.uint8)   # col 2i+1 -> high nibble
            packed = (lo | (hi << 4)).astype(np.uint8)  # [out, in/2]
            packed.tofile(os.path.join(out_dir, base + ".bin"))
            save_scale(base, scale)
        else:
            save_fp16(base + ".bin", W)

    save_fp16("embed.bin", sd["model.embed_tokens.weight"])
    save_fp16("final_norm.bin", sd["model.norm.weight"])
    save_fp16("lm_head.bin", sd.get("lm_head.weight", sd["model.embed_tokens.weight"]))

    for l in range(LAYERS):
        p = f"model.layers.{l}."
        save_fp16(f"layer{l:02d}_attn_norm.bin", sd[p + "input_layernorm.weight"])
        save_fp16(f"layer{l:02d}_ffn_norm.bin", sd[p + "post_attention_layernorm.weight"])
        qkv = torch.cat([
            sd[p + "self_attn.q_proj.weight"],
            sd[p + "self_attn.k_proj.weight"],
            sd[p + "self_attn.v_proj.weight"],
        ], dim=0)
        save_lin(f"layer{l:02d}_qkv", qkv)
        if ATTN_BIAS:
            qkv_bias = torch.cat([
                sd[p + "self_attn.q_proj.bias"],
                sd[p + "self_attn.k_proj.bias"],
                sd[p + "self_attn.v_proj.bias"],
            ], dim=0)
            save_fp16(f"layer{l:02d}_qkv_bias.bin", qkv_bias)  # bias stays fp16 regardless of dtype
        save_lin(f"layer{l:02d}_o", sd[p + "self_attn.o_proj.weight"])
        gate_up = torch.cat([
            sd[p + "mlp.gate_proj.weight"],
            sd[p + "mlp.up_proj.weight"],
        ], dim=0)
        save_lin(f"layer{l:02d}_gate_up", gate_up)
        save_lin(f"layer{l:02d}_down", sd[p + "mlp.down_proj.weight"])
        print(f"  exported layer {l:02d}")

    if LORA:
        export_lora(out_dir)

    tok = AutoTokenizer.from_pretrained(SOURCE)
    prompt = os.environ.get("JAC_PROMPT", "The capital of France is")
    ids = tok(prompt, return_tensors="np").input_ids.astype(np.int32).reshape(-1)
    ids.tofile(os.path.join(out_dir, "test_tokens.bin"))
    print(f"\ntest_tokens.bin: {ids.tolist()}   prompt={prompt!r}")

    with torch.no_grad():
        # The CUDA runtime emits a fixed number of raw argmax tokens. Override
        # repo generation_config settings (notably Qwen's repetition penalty)
        # and EOS stopping so this reference follows the same decoding rule.
        gen = model.generate(
            torch.tensor([ids.astype(np.int64)], device=device),
            max_new_tokens=20, do_sample=False, num_beams=1,
            repetition_penalty=1.0, eos_token_id=None,
            temperature=1.0, top_p=1.0, top_k=0,
        )
    cont = gen[0, len(ids):].tolist()
    print(f"REFERENCE greedy next-20 token ids: {cont}")
    print(f"REFERENCE text: {tok.decode(gen[0])!r}")
    print("\nThe generated CUDA runtime's emitted token ids should match (int8 may diverge later).")


def _load_adapter(source):
    # Load a peft adapter's tensors (safetensors preferred, else .bin). `source` may be a HF repo
    # id or a local directory. Returns a dict of {key: tensor-like with .shape and numpy via np.asarray}.
    from huggingface_hub import hf_hub_download

    def fetch(fname):
        if os.path.isdir(source):
            p = os.path.join(source, fname)
            return p if os.path.exists(p) else None
        try:
            return hf_hub_download(source, fname)
        except Exception:
            return None

    st = fetch("adapter_model.safetensors")
    if st is not None:
        from safetensors.torch import load_file
        return load_file(st)
    bn = fetch("adapter_model.bin")
    if bn is not None:
        return torch.load(bn, map_location="cpu", weights_only=True)  # tensors only; avoid unpickle RCE
    raise SystemExit(f"no adapter_model.safetensors/.bin found at {source!r}")


def export_lora(out_dir):
    # Export peft LoRA A/B for each target into the runtime's layout:
    #   layer{l}_w{q,k,v,o}_loraA.bin  = A [rank, in]   (peft lora_A.weight)
    #   layer{l}_w{q,k,v,o}_loraB.bin  = B [out, rank]  (peft lora_B.weight)
    # peft keys look like `...layers.{l}.self_attn.{proj}_proj.lora_{A,B}.weight` (with an optional
    # adapter-name infix like `.default.`), so we match by suffix fragment.
    proj = {"w_q": "q_proj", "w_k": "k_proj", "w_v": "v_proj", "w_o": "o_proj"}
    print(f"loading LoRA adapter from {LORA_SOURCE} ...")
    ad = _load_adapter(LORA_SOURCE)

    def find(layer, pname, ab):
        frag = f"layers.{layer}.self_attn.{pname}.lora_{ab}"
        hits = [v for k, v in ad.items() if frag in k and k.endswith("weight")]
        if not hits:
            raise SystemExit(f"adapter missing lora_{ab} for layer {layer} {pname}")
        return np.asarray(hits[0].detach().cpu().numpy() if hasattr(hits[0], "detach") else hits[0], dtype=np.float16)

    for l in range(LAYERS):
        for tgt in LORA_TARGETS:
            tag = tgt.replace("_", "")  # "w_q" -> "wq"
            find(l, proj[tgt], "A").tofile(os.path.join(out_dir, f"layer{l:02d}_{tag}_loraA.bin"))
            find(l, proj[tgt], "B").tofile(os.path.join(out_dir, f"layer{l:02d}_{tag}_loraB.bin"))
    print(f"exported LoRA adapter ({len(LORA_TARGETS)} targets x {LAYERS} layers)")


if __name__ == "__main__":
    main()
